const block=(slug,type,n,values)=>({id:`${slug}-${type}-${n}`,type,...values});
const h=(s,n,text)=>block(s,"heading",n,{level:2,text});
const p=(s,n,text)=>block(s,"paragraph",n,{text});
const bullets=(s,n,title,items)=>block(s,"bullets",n,{title,items});
const checklist=(s,n,title,items)=>block(s,"checklist",n,{title,items});
const table=(s,n,title,headers,rows)=>block(s,"table",n,{title,headers,rows});
const tip=(s,n,title,body)=>block(s,"tip",n,{label:"CURATED TIP",title,body});
const internal=(s,n,item)=>block(s,"internal_link",n,{eyebrow:"KEEP EXPLORING",title:item.title,body:item.body,anchor:item.anchor,url:`/article/${item.slug}`});
const sources=(s,n,items)=>block(s,"source_list",n,{title:"Sources and standards behind this guide",items});
const faq=(s,n,items)=>block(s,"faq",n,{title:"Frequently asked questions",items});
const pin=(s,title,description)=>block(s,"pinterest_asset",1,{title:"Save the visual guide",image:`/pinterest/verticals/${s}.png`,imageAlt:`Pinterest guide graphic for ${title}`,pinTitle:title,pinDescription:description});

